  /// The title of the section used for display purposes in the user interface.
  name String

  /// A unique code identifier for the section, used to reference the section
  /// in code and other internal systems.
  code String

  /// Timestamp when the section was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the section was last updated.
