  value String?

  /// Detailed explanation of what this configuration key controls and its
  /// potential values.
  description String?

  /// Timestamp when this configuration setting was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when this configuration setting was last modified.
  updated_at DateTime @db.Timestamptz

  /// Timestamp when this configuration setting was marked for deletion (soft
