  href String

  /// Referrer URL from which the user arrived at the system.
  referrer String

  /// Timestamp when the session was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the session expires for security purposes.
  expired_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  customer shopping_mall_customers @relation(fields: [customer_id], references: [id], onDelete: Cascade)

  @@index([customer_id, created_at])
